function brokerNode(name, expectedRpc) {
  const out = $(name).first().json || {};

  if (out.broker !== 'supabase') {
    throw new Error(`${name}: expected supabase broker`);
  }
  if (out.broker_version !== 'SB-BROKER-V3.0.0') {
    throw new Error(`${name}: expected SB-BROKER-V3.0.0, got ${out.broker_version}`);
  }
  if (out.rpc_name !== expectedRpc) {
    throw new Error(`${name}: RPC mismatch ${out.rpc_name}`);
  }
  return Array.isArray(out.response) ? out.response : [];
}

const funnelRows = brokerNode(
  'Supabase V3 - Funnel Report',
  'gtm_project01_funnel_report_v1'
);
const contactRows = brokerNode(
  'Supabase V3 - Contact State Report',
  'gtm_project01_contact_state_report_v1'
);
const qaRows = brokerNode(
  'Supabase V3 - QA Report',
  'gtm_project01_qa_report_v1'
);

if (funnelRows.length !== 1) {
  throw new Error(`GTM 10 expected one funnel report, got ${funnelRows.length}`);
}
if (qaRows.length !== 1) {
  throw new Error(`GTM 10 expected one QA report, got ${qaRows.length}`);
}
if (contactRows.length !== 7) {
  throw new Error(`GTM 10 expected 7 contact-state rows, got ${contactRows.length}`);
}

const funnel = funnelRows[0];
const qa = qaRows[0];

const counts = qa.counts || {};

const contactChecks = {
  all_crm_linked:
    contactRows.every(x => Boolean(x.hubspot_external_contact_id)),
  all_queued:
    contactRows.every(x => x.lifecycle_stage === 'queued'),
  all_planned:
    contactRows.every(x => x.outreach_task_status === 'planned'),
  all_zero_attempt:
    contactRows.every(x => Number(x.outreach_attempt_count) === 0),
  all_pending:
    contactRows.every(x => x.message_approval_status === 'pending'),
  all_send_blocked:
    contactRows.every(x => x.send_ready === false)
};

const expected =
  funnel.report_version === 'QA-V1.0.0' &&
  qa.qa_version === 'QA-V1.0.0' &&
  qa.state === 'PRE_SEND_CONTROLLED' &&
  qa.all_checks_pass === true &&

  Number(counts.contacts_total) === 7 &&
  Number(counts.outbound_ready_total) === 7 &&
  Number(counts.hubspot_links) === 7 &&
  Number(counts.distinct_hubspot_ids) === 7 &&
  Number(counts.outreach_tasks) === 7 &&
  Number(counts.planned_tasks) === 7 &&
  Number(counts.total_attempts) === 0 &&
  Number(counts.tasks_with_provider_message) === 0 &&
  Number(counts.active_renders) === 7 &&
  Number(counts.pending_renders) === 7 &&
  Number(counts.send_ready_rows) === 0 &&
  Number(counts.queued_rows) === 7 &&
  Number(counts.provider_events) === 0 &&
  Number(counts.reply_events) === 0 &&
  Number(counts.active_suppressions) === 0 &&

  Object.values(contactChecks).every(Boolean);

if (!expected) {
  throw new Error('GTM 10 final QA invariants did not match PRE_SEND_CONTROLLED baseline');
}

return [{
  json: {
    gtm10_reporting_qa_completed: true,

    broker_workflow_id: 'SUPABASE_BROKER_V3_WORKFLOW_ID',
    broker_version: 'SB-BROKER-V3.0.0',

    report_version: funnel.report_version,
    qa_version: qa.qa_version,
    qa_state: qa.state,
    qa_all_checks_pass: qa.all_checks_pass,

    scored_accounts: Number(funnel.accounts?.scored_account_rows ?? 0),
    contact_eligible_accounts: Number(funnel.accounts?.contact_eligible_account_rows ?? 0),

    canonical_contacts: Number(funnel.contacts?.canonical_contacts ?? 0),
    outbound_ready_contacts: Number(funnel.contacts?.outbound_ready_contacts ?? 0),

    hubspot_links: Number(funnel.crm?.hubspot_links ?? 0),

    outreach_tasks: Number(funnel.outreach?.tasks_total ?? 0),
    outreach_attempts: Number(funnel.outreach?.total_attempts ?? 0),

    pending_message_renders: Number(funnel.messages?.pending_renders ?? 0),
    send_ready_rows: Number(funnel.messages?.send_ready_rows ?? 0),

    queued_contacts: Number(funnel.lifecycle?.queued ?? 0),

    provider_events: Number(funnel.events?.provider_events ?? 0),
    reply_events: Number(funnel.events?.reply_events ?? 0),
    active_suppressions: Number(funnel.events?.active_suppressions ?? 0),

    smtp2go_live_enabled: Boolean(funnel.provider?.smtp2go_live_enabled),

    contact_state_rows: contactRows.length,
    contact_checks: contactChecks,

    credentials_required_in_parent: false,

    gtm10_all_checks_pass: true,

    next_stage:
      'Run final system audit, consolidate GTM 05/06, archive engineering-history workflows, and package Project 01 for portfolio/GitHub.'
  }
}];
